630					<h3>Interactive Counter</h3>
631					<p>This counter demonstrates state management and ARIA live regions for accessible dynamic content.</p>
632					<div class="counter">
633						<button id="decrease" type="button" aria-label="Decrease count by 1">−</button>
634						<output id="count" aria-live="off">0</output>
635						<button id="increase" type="button" aria-label="Increase count by 1">+</button>
636						<button id="reset" type="button" aria-label="Reset count to zero">Reset</button>
637					</div>
638					<div class="live-region" aria-live="polite" aria-atomic="true">
639						<span id="count-message"></span>
640					</div>
641				</article>
