703		<script>
704			const themeToggle = document.getElementById('theme-toggle');
705			const htmlElement = document.documentElement;
706			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
707	
708			const themeColors = { light: '#ffffff', dark: '#121212' };
709			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
710			themeColorMetas.forEach((meta) => {
711				meta.dataset.defaultContent = meta.content;
712			});
713	
714			const updateThemeUI = () => {
715				const forced = htmlElement.dataset.theme;
716				const isDark = forced ? forced === 'dark' : prefersDark.matches;
717				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
718				themeToggle.textContent = isDark ? '☀️' : '🌙';
719				themeToggle.setAttribute('aria-label', label);
720				themeToggle.title = label;
721				themeColorMetas.forEach((meta) => {
722					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
723				});
724			};
725	
726			if (themeToggle) {
727				themeToggle.hidden = false;
728				updateThemeUI();
729	
730				themeToggle.addEventListener('click', () => {
731					const systemTheme = prefersDark.matches ? 'dark' : 'light';
732					const current = htmlElement.dataset.theme || systemTheme;
733					const next = current === 'dark' ? 'light' : 'dark';
734					// Choosing the system theme clears the override so the page follows the OS again.
735					try {
736						if (next === systemTheme) {
737							delete htmlElement.dataset.theme;
738							localStorage.removeItem('theme');
739						} else {
740							htmlElement.dataset.theme = next;
741							localStorage.setItem('theme', next);
742						}
743					} catch {}
744					updateThemeUI();
745				});
746	
747				prefersDark.addEventListener('change', () => {
748					if (!htmlElement.dataset.theme) {
749						updateThemeUI();
750					}
751				});
752			}
753	
754			const copyrightYear = document.getElementById('copyright-year');
755			if (copyrightYear) {
756				copyrightYear.textContent = String(new Date().getFullYear());
757			}
758	
759			const messages = [
760				"This update was announced to screen readers!",
761				"Dynamic content updates work with aria-live regions.",
762				"Live regions are essential for accessible web apps.",
763				"Try this with a screen reader like NVDA or JAWS!"
764			];
765			let nextMessage = 0;
766			let count = 0;
767			const announceBtn = document.getElementById('announce');
768			const liveMessage = document.getElementById('live-message');
769			const contactForm = document.getElementById('contact-form');
770			const emailInput = document.getElementById('email');
771			const messageInput = document.getElementById('message');
772			const messageCount = document.getElementById('message-count');
773			const formStatus = document.getElementById('form-status');
774			const countDisplay = document.getElementById('count');
775			const countMessage = document.getElementById('count-message');
776			const decreaseBtn = document.getElementById('decrease');
777			const increaseBtn = document.getElementById('increase');
778			const resetBtn = document.getElementById('reset');
779	
780			const updateCountDisplay = () => {
781				countDisplay.textContent = String(count);
782				countMessage.textContent = `Count is ${count}.`;
783			};
784	
785			if (countDisplay && countMessage) {
786				decreaseBtn?.addEventListener('click', () => {
787					count--;
788					updateCountDisplay();
789				});
790	
791				increaseBtn?.addEventListener('click', () => {
792					count++;
793					updateCountDisplay();
794				});
795	
796				resetBtn?.addEventListener('click', () => {
797					count = 0;
798					updateCountDisplay();
799				});
800			}
801	
802			if (announceBtn && liveMessage) {
803				announceBtn.addEventListener('click', () => {
804					liveMessage.textContent = messages[nextMessage];
805					nextMessage = (nextMessage + 1) % messages.length;
806				});
807			}
808	
809			if (contactForm) {
810				const emailError = document.getElementById('email-error');
811	
812				const updateMessageCount = () => {
813					if (messageInput && messageCount) {
814						const remaining = messageInput.maxLength - messageInput.value.length;
815						messageCount.textContent = remaining.toLocaleString();
816					}
817				};
818	
819				messageInput?.addEventListener('input', updateMessageCount);
820				// Browsers may restore field values on back/forward navigation.
821				window.addEventListener('pageshow', updateMessageCount);
822				updateMessageCount();
823	
824				const setEmailError = (message) => {
825					emailError.textContent = message;
826					if (message) {
827						emailInput.setAttribute('aria-invalid', 'true');
828						emailInput.setAttribute('aria-describedby', 'email-error email-help');
829					} else {
830						emailInput.removeAttribute('aria-invalid');
831						emailInput.setAttribute('aria-describedby', 'email-help');
832					}
833				};
834	
835				const validateEmail = () => {
836					let message = '';
837					if (emailInput.validity.valueMissing) {
838						message = 'Enter your email address.';
839					} else if (!emailInput.validity.valid) {
840						message = 'Enter an email address in the format name@example.com.';
841					}
842					setEmailError(message);
843					return !message;
844				};
845	
846				emailInput.addEventListener('blur', () => {
847					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
848						validateEmail();
849					}
850				});
851	
852				emailInput.addEventListener('input', () => {
853					if (emailInput.hasAttribute('aria-invalid')) {
854						validateEmail();
855					}
856				});
857	
858				contactForm.addEventListener('input', () => {
859					formStatus.textContent = '';
860				});
861	
862				contactForm.addEventListener('submit', async (event) => {
863					event.preventDefault();
864					const submitBtn = contactForm.querySelector('button[type="submit"]');
865					if (submitBtn.getAttribute('aria-disabled') === 'true') {
866						return;
867					}
868					formStatus.textContent = '';
869					if (!validateEmail()) {
870						emailInput.focus();
871						return;
872					}
873					const originalText = submitBtn.textContent;
874					// aria-disabled keeps keyboard focus on the button, unlike the disabled attribute.
875					submitBtn.setAttribute('aria-disabled', 'true');
876					submitBtn.textContent = 'Sending…';
877					formStatus.textContent = 'Sending your message…';
878					await new Promise(resolve => setTimeout(resolve, 800));
879					contactForm.reset();
880					setEmailError('');
881					updateMessageCount();
882					submitBtn.removeAttribute('aria-disabled');
883					submitBtn.textContent = originalText;
884					formStatus.textContent = "Thanks! This is a demo, so nothing was sent.";
885					emailInput.focus();
886				});
887			}
888		</script>
